const $=s=>document.querySelector(s),date=s=>s.split('-').reverse().join('/');let token=null;
const result=$('#import-result'),save=$('#import-save'),check=$('#import-check');
async function api(path,payload){const r=await fetch('/api/import/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const b=await r.json();if(!r.ok)throw Error(b.error||'Não foi possível importar.');return b;}
const fileData=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Falha ao ler '+file.name));reader.onload=()=>resolve({name:file.name,content:reader.result.split(',')[1]});reader.readAsDataURL(file);});
$('#import-form').onchange=()=>{token=null;save.hidden=true;result.textContent='Arquivos alterados. Confira novamente antes de salvar.';};
$('#import-form').onsubmit=async e=>{e.preventDefault();check.disabled=true;save.hidden=true;token=null;result.textContent='Lendo relatórios e conferindo saldos…';try{const files=['#import-csv','#import-profile','#import-stock'].map(s=>$(s).files[0]);if(files.some(f=>!f))throw Error('Selecione os três arquivos.');if(files.reduce((s,f)=>s+f.size,0)>30*1024*1024)throw Error('O lote deve ter até 30 MB.');const r=await api('preview',{files:await Promise.all(files.map(fileData))});result.textContent=`Data do relatório: ${date(r.date)}. ${r.counts.requests} necessidades, ${r.counts.params} perfis, ${r.counts.movements} movimentos e ${r.counts.stocks} saldos conferidos. O CSV será associado à data dos PDFs. `+(r.duplicate?'Este lote já está no histórico; nenhuma duplicação será feita.':r.conflict?'Já existe outro lote nesta data. O histórico foi preservado; este lote não pode ser salvo.':'Pronto para salvar.');if(!r.conflict&&!r.duplicate){token=r.id;save.hidden=false;}}catch(e){result.textContent='Não importado: '+e.message;}finally{check.disabled=false;}};
save.onclick=async()=>{if(!token)return;save.disabled=true;check.disabled=true;try{await api('commit',{id:token});result.textContent='Lote salvo. Carregando a base atualizada…';location.reload();}catch(e){result.textContent='Não foi possível concluir: '+e.message;save.disabled=false;check.disabled=false;}};
try{const data=await (await fetch('/data.json')).json();const rows=[...(data.meta.erpImports||[])].sort((a,b)=>b.date.localeCompare(a.date));$('#import-history').replaceChildren(...rows.map(r=>{const div=document.createElement('p');div.textContent=`${date(r.date)} · ${r.counts.requests} necessidades · ${r.counts.params} perfis · ${r.counts.stocks} saldos · ${r.counts.movements} movimentos`;return div;}));if(!rows.length)$('#import-history').textContent='Nenhum lote importado ainda.';}catch{$('#import-history').textContent='Não foi possível carregar o histórico.';}
